px}.n502-prose{max-width:1000px;padding-top:55px;padding-bottom:55px;line-height:1.8}.n502-prose>img{width:100%;max-height:600px;object-fit:cover}.n502-form{display:grid;gap:15px;max-width:800px;padding-top:55px;padding-bottom:55px}.n502-form input,.n502-form textarea,.n502-form select{padding:14px;border:1px solid #ddd;font:inherit}.n502-form textarea{min-height:150px}
